(()=>{document.querySelectorAll('.music-stack').forEach(stack=>{const cards=[...stack.querySelectorAll('.music-pop-card')],counter=stack.querySelector('[aria-live]');let active=0;function move(step){active=(active+step+cards.length)%cards.length;cards.forEach((card,index)=>{let slot=(index-active+cards.length)%cards.length;card.style.setProperty('--slot',slot);card.style.zIndex=String(slot+1)});counter.textContent=String(active+1).padStart(2,'0')+' / 04'}stack.querySelectorAll('[data-step]').forEach(button=>button.addEventListener('click',()=>move(Number(button.dataset.step))));stack.addEventListener('keydown',event=>{if(event.key==='ArrowRight'||event.key==='ArrowLeft'){event.preventDefault();move(event.key==='ArrowRight'?1:-1)}});let start=null;const stage=stack.querySelector('.music-stack-stage');stage.addEventListener('touchstart',event=>{start=event.touches[0].clientX},{passive:true});stage.addEventListener('touchend',event=>{if(start!==null){let delta=event.changedTouches[0].clientX-start;if(Math.abs(delta)>45)move(delta<0?1:-1);start=null}},{passive:true});move(0)})})();
(()=>{const reduced=matchMedia('(prefers-reduced-motion: reduce)');if(!matchMedia('(hover:hover) and (pointer:fine)').matches)return;document.querySelectorAll('.music-pop-card').forEach(card=>{let frame=0;card.addEventListener('pointermove',e=>{if(reduced.matches)return;const r=card.getBoundingClientRect(),x=(e.clientX-r.left)/r.width-.5,y=(e.clientY-r.top)/r.height-.5;cancelAnimationFrame(frame);frame=requestAnimationFrame(()=>{card.style.setProperty('--depth-x',(-y*10)+'deg');card.style.setProperty('--depth-y',(x*12)+'deg')})});card.addEventListener('pointerleave',()=>{cancelAnimationFrame(frame);card.style.setProperty('--depth-x','0deg');card.style.setProperty('--depth-y','0deg')})})})();
